String coverKey = tools.getPrimaryPage().getString(".pxCoverInsKey");
// first check if pyWorkCover is our cover case
if(pega_rules_page.PageExistsWithClass(coverPage, tools)){
  try{
	if(coverKey.equals(tools.getDatabase().getHandle(tools.findPage(coverPage)))){		  
	  return true;
	}
  }catch (DatabaseException ex) {	}      
}
// check if we have cover page in the clipboard.
ClipboardPage cpCoverPage = tools.findPageByHandle(coverKey);
ClipboardPage tempPage = null;
String createCover="";
if(cpCoverPage!=null && "pyTopCaseWork".equalsIgnoreCase(cpCoverPage.getName()))
{
 if (cpCoverPage.removeFromClipboard()) {
						 tempPage = tools.findPageByHandle(coverKey);
						if (tempPage != null) { 
                           cpCoverPage = tempPage;                         
                        }
   else{
     createCover="create";
   }
 }
}
// If the cover page is not present in the clipboard 
if(cpCoverPage == null || (cpCoverPage!=null && "create".equals(createCover))){  
  // try to give unique name to coverpage
  int count = 0;
  String candidateCoverName = "pyWorkCover";
  while (tools.findPage(candidateCoverName) != null)
  {
    count++;
    candidateCoverName = "pyWorkCover_" + count;
  }
  coverPage = candidateCoverName;
  nextBlock = "OPEN";
}else{

  //if we have the cover page on the clipbaord
  coverPage = cpCoverPage.getName();

}

ClipboardPage cpOpenResult = null;    
    try{
      //call OpenIfStale to get the latest form DB maintaining the locking strategy
      cpOpenResult = tools.getDatabase().openIfStale(myStepPage, true, true, true, null,false,true,true);
      if (cpOpenResult != null) {
        // HFix-36067 making sure we always have the latest either DB or current page
        if(myStepPage.getIfPresent(".pxUpdateDateTime")==null || (pega_rules_datetime.CompareDates(cpOpenResult.getString(".pxUpdateDateTime"), myStepPage.getString(".pxUpdateDateTime")))) {          
          cpOpenResult.rename(coverPage);
        }        
      } else {
       tools.getStepStatus().set(ProcessingStatus.SEVERITY_FAIL, "Database-Instance-NotFound",((PegaDatabase) (tools.getDatabase())).generateKeyList(myStepPage));                       
      }
    }catch(DatabaseException dbEx){
      oLog.error("Error in Obj-Refresh-And-Lock", dbEx);
    }
